//! **A file whose own `id` column cannot serve, opened on the session tier by the caller's
//! choice** (ADR-016, Amendment 3) — exercised against real GeoParquet files.
//!
//! Every file here is generated by `spatial_engine::fixture`; none is a file from anyone's disk.
//!
//! **What this file does not count.** The whole-column uniqueness scan's counter
//! (`identity_verification_scans`) is process-wide, and these tests run in parallel with each
//! other, so a delta read here would race. The scan counts of the choice are asserted in
//! `text_id_set_aside_scan_counts.rs`, which holds one test.

use std::path::PathBuf;

use spatial_engine::fixture::{write_geoparquet, FixtureSpec, IdentityMode};
use spatial_engine::identity::{IdSource, IdUniqueness, IdentityDeclaration};
use spatial_engine::{
    AdmittedPredicate, CancelToken, Dataset, EngineError, FilterError, PoolConfig,
    PredicateAdmitError,
};

fn write(name: &str, identity: IdentityMode) -> PathBuf {
    let dir =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../target/fixtures/text-id-set-aside");
    std::fs::create_dir_all(&dir).expect("fixture dir");
    let path = dir.join(format!("{name}.parquet"));
    let spec = FixtureSpec {
        features: 500,
        avg_vertices: 12,
        identity,
        ..Default::default()
    };
    write_geoparquet(&path, &spec).expect("write fixture");
    path
}

/// The caller's choice, with no declaration, assertion or cancel.
fn open_setting_aside(path: &std::path::Path) -> Result<Dataset, EngineError> {
    Dataset::open_cancellable_setting_aside_file_id(
        path,
        None,
        None,
        &CancelToken::new(),
        PoolConfig::default(),
    )
}

/// The identity the open admitted, asserted to be the session tier's by the caller's choice.
fn assert_set_aside_session_tier(dataset: &Dataset) {
    let identity = dataset.identity();
    assert!(identity.source().is_session_ordinal(), "the session tier");
    assert_eq!(*identity.source(), IdSource::SessionOrdinal);
    assert_eq!(
        identity.uniqueness(),
        IdUniqueness::ByConstructionWithinGeneration
    );
    assert_eq!(
        identity.set_aside_column(),
        Some("id"),
        "the choice is recorded on the identity"
    );
}

/// N-1 of the form's §4; its recorded mutation is M-1.
#[test]
fn file_a_text_id_with_no_integer_column_opens_on_the_session_tier_when_set_aside() {
    let path = write("file-a", IdentityMode::StringIds);

    // Control: with no choice the same file is refused for its `id` column.
    match Dataset::open(&path) {
        Err(EngineError::IdentityUnusable { column, .. }) => assert_eq!(column, "id"),
        other => panic!(
            "a text `id` must be refused without the choice: {:?}",
            other.err()
        ),
    }

    let dataset = open_setting_aside(&path).expect("the choice opens the file");
    assert_set_aside_session_tier(&dataset);
    assert!(
        dataset.identity().candidate_columns().is_empty(),
        "file A holds no integer column to offer: {:?}",
        dataset.identity().candidate_columns()
    );
}

/// N-2 of the form's §4; its recorded mutation is M-2.
#[test]
fn file_b_set_aside_opens_by_row_position_and_lists_parcel_key() {
    let path = write("file-b", IdentityMode::StringIdsBesideParcelKey);

    // Control: the plain refusal offers `parcel_key` as a column that could be declared.
    match Dataset::open(&path) {
        Err(EngineError::IdentityUnusable {
            candidate_columns, ..
        }) => {
            assert!(candidate_columns.iter().any(|c| c == "parcel_key"))
        }
        other => panic!(
            "a text `id` must be refused without the choice: {:?}",
            other.err()
        ),
    }

    let dataset = open_setting_aside(&path).expect("the choice opens the file");
    assert_set_aside_session_tier(&dataset);
    assert!(
        !matches!(dataset.identity().source(), IdSource::Mapped { .. }),
        "the choice never maps a candidate"
    );
    assert_eq!(
        dataset.identity().candidate_columns(),
        ["parcel_key".to_string()],
        "the candidates are the file's other admissible columns"
    );
}

/// N-3 of the form's §4; its recorded mutation is M-3b (M-3 fails `the_set_aside_scan_counts_are_exact`).
#[test]
fn a_repeating_integer_id_is_scanned_again_then_set_aside() {
    let path = write("repeating", IdentityMode::DuplicateIds);

    // Control: a plain open refuses the repeated values, after its scan.
    match Dataset::open(&path) {
        Err(EngineError::IdentityUnusable { column, detail, .. }) => {
            assert_eq!(column, "id");
            assert!(!detail.is_empty());
        }
        other => panic!("repeated values must be refused: {:?}", other.err()),
    }

    let dataset = open_setting_aside(&path).expect("the choice opens the file");
    assert_set_aside_session_tier(&dataset);
    assert!(
        !dataset
            .identity()
            .candidate_columns()
            .iter()
            .any(|c| c == "id"),
        "the column set aside is not offered as a candidate: {:?}",
        dataset.identity().candidate_columns()
    );
}

/// N-4 of the form's §4; its recorded mutation is M-4.
#[test]
fn a_negative_integer_id_is_set_aside_after_its_scan() {
    let path = write("negative", IdentityMode::NegativeIds);

    match Dataset::open(&path) {
        Err(EngineError::IdentityUnusable { column, .. }) => assert_eq!(column, "id"),
        other => panic!("a negative `id` must be refused: {:?}", other.err()),
    }

    let dataset = open_setting_aside(&path).expect("the choice opens the file");
    assert_set_aside_session_tier(&dataset);
    assert!(
        !dataset
            .identity()
            .candidate_columns()
            .iter()
            .any(|c| c == "id"),
        "the column set aside is not offered as a candidate"
    );
}

/// N-5 of the form's §4; its recorded mutation is M-5.
#[test]
fn the_set_aside_is_refused_by_name_for_a_file_with_no_id_column() {
    let path = write("no-id", IdentityMode::ForeignKeyColumn);

    // Control: with no choice the file opens on the session tier, with nothing set aside.
    let plain = Dataset::open(&path).expect("a file with no `id` column opens");
    assert!(plain.identity().source().is_session_ordinal());
    assert_eq!(plain.identity().set_aside_column(), None);

    match open_setting_aside(&path) {
        Err(error @ EngineError::IdentitySetAsideRefused { .. }) => assert_eq!(
            error.to_string(),
            "refused: the file has no column named `id` to set aside"
        ),
        other => panic!("expected the named refusal: {:?}", other.err()),
    }
}

/// N-6 of the form's §4; its recorded mutation is M-6.
#[test]
fn the_set_aside_is_refused_by_name_when_the_id_serves() {
    let path = write("serves", IdentityMode::NativeUnique);

    // Control: with no choice the file opens on its own `id`.
    let plain = Dataset::open(&path).expect("a serving `id` opens");
    assert_eq!(*plain.identity().source(), IdSource::File);

    match open_setting_aside(&path) {
        Err(error @ EngineError::IdentitySetAsideRefused { .. }) => assert_eq!(
            error.to_string(),
            "refused: the file's own `id` column serves as its identity, so it cannot be set aside"
        ),
        other => panic!("expected the named refusal: {:?}", other.err()),
    }
}

/// N-7 of the form's §4; its mutation M-7 fails `the_set_aside_scan_counts_are_exact`, not this test.
#[test]
fn a_set_aside_with_a_declared_column_is_refused_before_any_scan() {
    let path = write("declared", IdentityMode::StringIdsBesideParcelKey);
    let declaration =
        || IdentityDeclaration::new("parcel_key", "integration-test", "2026-11-27T00:00:00Z");

    // Control: the declaration alone opens the file on a mapped identity.
    let plain = Dataset::open_with_declared_identity(&path, declaration(), &CancelToken::new())
        .expect("the declaration alone opens");
    assert!(matches!(plain.identity().source(), IdSource::Mapped { .. }));

    let result = Dataset::open_cancellable_setting_aside_file_id(
        &path,
        None,
        Some(declaration()),
        &CancelToken::new(),
        PoolConfig::default(),
    );
    match result {
        Err(error @ EngineError::IdentitySetAsideRefused { .. }) => assert_eq!(
            error.to_string(),
            "refused: setting aside the file's `id` column cannot be combined with a declared identity column"
        ),
        other => panic!("expected the named refusal: {:?}", other.err()),
    }
}

/// N-8 of the form's §4; its recorded mutation is M-8.
#[test]
fn a_predicate_naming_id_on_a_set_aside_open_is_refused_as_ambiguous() {
    let path = write("ambiguous", IdentityMode::StringIds);
    let dataset = open_setting_aside(&path).expect("the choice opens the file");

    match AdmittedPredicate::admit("id = 'key-1'", &dataset) {
        Err(PredicateAdmitError::Filter(error @ FilterError::IdentityAliasAmbiguous { .. })) => {
            assert!(matches!(
                error,
                FilterError::IdentityAliasAmbiguous {
                    ref column,
                    ref source_column,
                    by_row_position: true,
                } if column == "id" && source_column == "file_row_number"
            ));
            assert_eq!(
                error.to_string(),
                "refused: `id` is ambiguous — this dataset is identified by row position for this \
                 session, and the file also carries its own column named `id`; a predicate cannot \
                 say which one it means"
            );
        }
        other => panic!("expected the ambiguity refusal: {:?}", other.err()),
    }

    // Control: a file with no `id` column refuses `id` as an unknown column, not as ambiguous.
    let no_id = write("ambiguous-control", IdentityMode::ForeignKeyColumn);
    let plain = Dataset::open(&no_id).expect("a file with no `id` column opens");
    match AdmittedPredicate::admit("id = 'key-1'", &plain) {
        Err(PredicateAdmitError::Filter(FilterError::UnknownColumn { column })) => {
            assert_eq!(column, "id")
        }
        other => panic!("expected an unknown column: {:?}", other.err()),
    }
}
